const m = require('zigbee-herdsman-converters/lib/modernExtend');
const exposes = require('zigbee-herdsman-converters/lib/exposes');
const fz = require('zigbee-herdsman-converters/converters/fromZigbee');
const tz = require('zigbee-herdsman-converters/converters/toZigbee');
const reporting = require('zigbee-herdsman-converters/lib/reporting');
const e = exposes.presets;
const ea = exposes.access;


const customExtend = {
  addCustomClusterConfig: (endpointNames) => {
    return m.deviceAddCustomCluster("customClusterConfig", {
      name: "customClusterConfig",
      ID: 0xfc10,
      manufacturerCode: 0x1141,
      endpointNames: endpointNames,
      attributes: {
        simple_click_device: {name: "simple_click_device", ID: 0x0001, type: 0x21, write: true},
        double_click_device: {name: "double_click_device", ID: 0x0002, type: 0x21, write: true},
        long_press_device:   {name: "long_press_device", ID: 0x0003, type: 0x21, write: true},
        relay_mode:          {name: "relay_mode", ID: 0x0004, type: 0x30, write: true},
        backlight_mode:      {name: "backlight_mode", ID: 0x0005, type: 0x30, write: true},
      },
      commands: {},
      commandsResponse: {},
    });
  },
}

function genEnumForEndpoint(epName) {
  return [
    m.enumLookup({
      endpointName: epName,
      name: "switch_mode",
      lookup: {toggle: 0, momentary: 1, multifunction: 2},
      cluster: "genOnOffSwitchCfg",
      attribute: {ID: 0x4000, type: 0x30},
      description: "Switch Mode",
      entityCategory: "config",
    }),
    m.enumLookup({
      endpointName: epName,
      name: "switch_actions",
      lookup: {on_off: 0, off_on: 1, toggle: 2},
      cluster: "genOnOffSwitchCfg",
      attribute: "switchActions",
      description: "Actions switch",
      entityCategory: "config",
    }),
    m.numeric({
        endpointNames: [epName],
        name: "simple_click_device",
        cluster: "customClusterConfig",
        attribute: {ID: 0x0001, type: 0x21},
        description: "Simple Click Device",
        entityCategory: "config",
    }),
    m.numeric({
        endpointNames: [epName],
        name: "double_click_device",
        cluster: "customClusterConfig",
        attribute: {ID: 0x0002, type: 0x21},
        description: "Double Click Device",
        entityCategory: "config",
    }),
    m.numeric({
        endpointNames: [epName],
        name: "long_press_device",
        cluster: "customClusterConfig",
        attribute: {ID: 0x0003, type: 0x21},
        description: "Long Press Device",
        entityCategory: "config",
    }),
    m.enumLookup({
        endpointName: epName,
        name: "relay_mode",
        lookup: {detached: 0, attached: 1},
        cluster: "customClusterConfig",
        attribute: {ID: 0x0004, type: 0x30},
        description: "Relay Mode",
        entityCategory: "config",
    }),
    m.enumLookup({
        endpointName: epName,
        name: "backlight_mode",
        lookup: {on: 0, off: 1, onoff: 2, offon: 3},
        cluster: "customClusterConfig",
        attribute: {ID: 0x0005, type: 0x30},
        description: "Backlight Mode",
        entityCategory: "config",
    }),
  ]
}

function genExtend(endpoints) {
  let endpointNames = Object.keys(endpoints);
  let features = [
    m.deviceEndpoints({"endpoints": endpoints}), 
    m.onOff({"powerOnBehavior": true, "endpointNames": endpointNames}), 
    m.commandsOnOff({"endpointNames": endpointNames}), 
    m.commandsLevelCtrl({"endpointNames": endpointNames}),
    m.identify({"endpointNames": endpointNames}),
    customExtend.addCustomClusterConfig(endpointNames),
  ];
  for (let i = 0; i < endpointNames.length; i++) {
    const epName = endpointNames[i];
    features.push(...genEnumForEndpoint(epName));
  }
  
  return features;
}

async function configureDevice(device, coordinatorEndpoint, logger) {
  // bind + configure reporting + read initial values for each endpoint
  for (const epId of Object.keys(device.endpoints)) {
    const ep = device.getEndpoint(parseInt(epId, 10));
    if (!ep) continue;

    // read initial values so Z2M/HA ont l'état au join
    await ep.read(0xfc10, [0x0001, 0x0002, 0x0003, 0x0004, 0x0005], {manufacturerCode: 0x1141});
  }
}

